SET NAMES utf8mb4;

CREATE TABLE IF NOT EXISTS konular (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  ders_kodu VARCHAR(50) NOT NULL,
  kod VARCHAR(120) NOT NULL,
  ad VARCHAR(190) NOT NULL,
  aciklama TEXT NULL,
  sira INT NOT NULL DEFAULT 0,
  aktif TINYINT(1) NOT NULL DEFAULT 1,
  PRIMARY KEY (id),
  UNIQUE KEY uk_konu_kod (kod),
  KEY ix_konu_ders (ders_kodu, sira)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS ders_icerikleri (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  konu_kodu VARCHAR(120) NOT NULL,
  kod VARCHAR(160) NOT NULL,
  baslik VARCHAR(190) NOT NULL,
  alt_baslik VARCHAR(190) NULL,
  icerik TEXT NOT NULL,
  ornek_metni TEXT NULL,
  sira INT NOT NULL DEFAULT 0,
  aktif TINYINT(1) NOT NULL DEFAULT 1,
  PRIMARY KEY (id),
  UNIQUE KEY uk_icerik_kod (kod),
  KEY ix_icerik_konu (konu_kodu, sira)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS sorular (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  konu_kodu VARCHAR(120) NOT NULL,
  kod VARCHAR(170) NOT NULL,
  soru_turu VARCHAR(40) NOT NULL DEFAULT 'coktan_secmeli',
  soru TEXT NOT NULL,
  secenekler_json LONGTEXT NULL,
  dogru_cevap TEXT NULL,
  aciklama TEXT NULL,
  zorluk TINYINT UNSIGNED NOT NULL DEFAULT 1,
  sira INT NOT NULL DEFAULT 0,
  aktif TINYINT(1) NOT NULL DEFAULT 1,
  PRIMARY KEY (id),
  UNIQUE KEY uk_soru_kod (kod),
  KEY ix_soru_konu (konu_kodu, sira)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS etkinlikler (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  konu_kodu VARCHAR(120) NOT NULL,
  kod VARCHAR(170) NOT NULL,
  tur VARCHAR(40) NOT NULL,
  baslik VARCHAR(190) NOT NULL,
  yonerge TEXT NOT NULL,
  odul_yildiz TINYINT UNSIGNED NOT NULL DEFAULT 1,
  sira INT NOT NULL DEFAULT 0,
  aktif TINYINT(1) NOT NULL DEFAULT 1,
  PRIMARY KEY (id),
  UNIQUE KEY uk_etkinlik_kod (kod),
  KEY ix_etkinlik_konu (konu_kodu, sira)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

