INSERT INTO ders_icerikleri (konu_kodu,kod,baslik,alt_baslik,icerik,ornek_metni,sira,aktif) VALUES ('turkce_kelimeler','turkce_kelimeler_c01','Keşfedelim','Kelimeler','Bugün Kelimeler konusuna giriş yapıyoruz. kelime ile başlayalım.','Örnek: kelime ile ilgili bir örneği birlikte inceleyelim.',1,1) ON DUPLICATE KEY UPDATE baslik=VALUES(baslik),alt_baslik=VALUES(alt_baslik),icerik=VALUES(icerik),ornek_metni=VALUES(ornek_metni),sira=VALUES(sira),aktif=1;
INSERT INTO ders_icerikleri (konu_kodu,kod,baslik,alt_baslik,icerik,ornek_metni,sira,aktif) VALUES ('turkce_kelimeler','turkce_kelimeler_c02','Birlikte Öğrenelim','Kelimeler','anlam kavramını kısa bir örnekle öğrenelim ve günlük hayatta nerede kullandığımızı düşünelim.','Örnek: anlam ile ilgili bir örneği birlikte inceleyelim.',2,1) ON DUPLICATE KEY UPDATE baslik=VALUES(baslik),alt_baslik=VALUES(alt_baslik),icerik=VALUES(icerik),ornek_metni=VALUES(ornek_metni),sira=VALUES(sira),aktif=1;
INSERT INTO ders_icerikleri (konu_kodu,kod,baslik,alt_baslik,icerik,ornek_metni,sira,aktif) VALUES ('turkce_kelimeler','turkce_kelimeler_c03','Hadi Deneyelim','Kelimeler','Kelimeler konusunda küçük bir uygulama yapalım. Önce örneği incele, sonra sen dene.','Örnek: varlık adı ile ilgili bir örneği birlikte inceleyelim.',3,1) ON DUPLICATE KEY UPDATE baslik=VALUES(baslik),alt_baslik=VALUES(alt_baslik),icerik=VALUES(icerik),ornek_metni=VALUES(ornek_metni),sira=VALUES(sira),aktif=1;
INSERT INTO ders_icerikleri (konu_kodu,kod,baslik,alt_baslik,icerik,ornek_metni,sira,aktif) VALUES ('turkce_kelimeler','turkce_kelimeler_c04','Düşün ve Söyle','Kelimeler','eylem ile ilgili kendi örneğini bul. Neden böyle düşündüğünü bir cümleyle anlat.','Örnek: eylem ile ilgili bir örneği birlikte inceleyelim.',4,1) ON DUPLICATE KEY UPDATE baslik=VALUES(baslik),alt_baslik=VALUES(alt_baslik),icerik=VALUES(icerik),ornek_metni=VALUES(ornek_metni),sira=VALUES(sira),aktif=1;
