INSERT INTO etkinlikler (konu_kodu,kod,tur,baslik,yonerge,odul_yildiz,sira,aktif) VALUES ('turkce_okuma_anlama','turkce_okuma_anlama_a01','mini_uygulama','Okuma ve Anlama: Hadi Deneyelim','kısa metin ve ana fikir ile ilgili iki küçük örnek bul ve yüksek sesle anlat.',1,1,1) ON DUPLICATE KEY UPDATE tur=VALUES(tur),baslik=VALUES(baslik),yonerge=VALUES(yonerge),odul_yildiz=VALUES(odul_yildiz),sira=VALUES(sira),aktif=1;
