INSERT INTO konular (ders_kodu,kod,ad,aciklama,sira,aktif) VALUES ('turkce','turkce_noktalama','Noktalama İşaretleri','Noktalama İşaretleri konusunda 1. sınıf seviyesinde temel kazanımlar ve uygulamalar.',6,1) ON DUPLICATE KEY UPDATE ad=VALUES(ad),aciklama=VALUES(aciklama),sira=VALUES(sira),aktif=1;
INSERT INTO ders_icerikleri (konu_kodu,kod,baslik,alt_baslik,icerik,ornek_metni,sira,aktif) VALUES ('turkce_noktalama','turkce_noktalama_c01','Keşfedelim','Noktalama İşaretleri','Bugün Noktalama İşaretleri konusuna giriş yapıyoruz. nokta ile başlayalım.','Örnek: nokta ile ilgili bir örneği birlikte inceleyelim.',1,1) ON DUPLICATE KEY UPDATE baslik=VALUES(baslik),alt_baslik=VALUES(alt_baslik),icerik=VALUES(icerik),ornek_metni=VALUES(ornek_metni),sira=VALUES(sira),aktif=1;
INSERT INTO ders_icerikleri (konu_kodu,kod,baslik,alt_baslik,icerik,ornek_metni,sira,aktif) VALUES ('turkce_noktalama','turkce_noktalama_c02','Birlikte Öğrenelim','Noktalama İşaretleri','soru işareti kavramını kısa bir örnekle öğrenelim ve günlük hayatta nerede kullandığımızı düşünelim.','Örnek: soru işareti ile ilgili bir örneği birlikte inceleyelim.',2,1) ON DUPLICATE KEY UPDATE baslik=VALUES(baslik),alt_baslik=VALUES(alt_baslik),icerik=VALUES(icerik),ornek_metni=VALUES(ornek_metni),sira=VALUES(sira),aktif=1;
INSERT INTO ders_icerikleri (konu_kodu,kod,baslik,alt_baslik,icerik,ornek_metni,sira,aktif) VALUES ('turkce_noktalama','turkce_noktalama_c03','Hadi Deneyelim','Noktalama İşaretleri','Noktalama İşaretleri konusunda küçük bir uygulama yapalım. Önce örneği incele, sonra sen dene.','Örnek: ünlem ile ilgili bir örneği birlikte inceleyelim.',3,1) ON DUPLICATE KEY UPDATE baslik=VALUES(baslik),alt_baslik=VALUES(alt_baslik),icerik=VALUES(icerik),ornek_metni=VALUES(ornek_metni),sira=VALUES(sira),aktif=1;
INSERT INTO ders_icerikleri (konu_kodu,kod,baslik,alt_baslik,icerik,ornek_metni,sira,aktif) VALUES ('turkce_noktalama','turkce_noktalama_c04','Düşün ve Söyle','Noktalama İşaretleri','virgül ile ilgili kendi örneğini bul. Neden böyle düşündüğünü bir cümleyle anlat.','Örnek: virgül ile ilgili bir örneği birlikte inceleyelim.',4,1) ON DUPLICATE KEY UPDATE baslik=VALUES(baslik),alt_baslik=VALUES(alt_baslik),icerik=VALUES(icerik),ornek_metni=VALUES(ornek_metni),sira=VALUES(sira),aktif=1;
INSERT INTO ders_icerikleri (konu_kodu,kod,baslik,alt_baslik,icerik,ornek_metni,sira,aktif) VALUES ('turkce_noktalama','turkce_noktalama_c05','Mini Tekrar','Noktalama İşaretleri','Bugün öğrendiğimiz Noktalama İşaretleri bilgisini tekrar ediyoruz. En önemli ipucu: büyük harf.','Örnek: büyük harf ile ilgili bir örneği birlikte inceleyelim.',5,1) ON DUPLICATE KEY UPDATE baslik=VALUES(baslik),alt_baslik=VALUES(alt_baslik),icerik=VALUES(icerik),ornek_metni=VALUES(ornek_metni),sira=VALUES(sira),aktif=1;
INSERT INTO sorular (konu_kodu,kod,soru_turu,soru,secenekler_json,dogru_cevap,aciklama,zorluk,sira,aktif) VALUES ('turkce_noktalama','turkce_noktalama_q01','coktan_secmeli','Noktalama İşaretleri konusunda ilk öğrendiğimiz kavram hangisidir?','["nokta","soru işareti","ünlem","rastgele"]','nokta','Bu konuda temel kavramlardan biri nokta.',1,1,1) ON DUPLICATE KEY UPDATE soru=VALUES(soru),secenekler_json=VALUES(secenekler_json),dogru_cevap=VALUES(dogru_cevap),aciklama=VALUES(aciklama),zorluk=VALUES(zorluk),sira=VALUES(sira),aktif=1;
INSERT INTO sorular (konu_kodu,kod,soru_turu,soru,secenekler_json,dogru_cevap,aciklama,zorluk,sira,aktif) VALUES ('turkce_noktalama','turkce_noktalama_q02','coktan_secmeli','Noktalama İşaretleri ile ilgili doğru seçeneği bul.','["soru işareti","ilgisiz cevap","yanlış seçenek","hiçbiri"]','soru işareti','soru işareti bu konunun içindedir.',1,2,1) ON DUPLICATE KEY UPDATE soru=VALUES(soru),secenekler_json=VALUES(secenekler_json),dogru_cevap=VALUES(dogru_cevap),aciklama=VALUES(aciklama),zorluk=VALUES(zorluk),sira=VALUES(sira),aktif=1;
