INSERT INTO etkinlikler (konu_kodu,kod,tur,baslik,yonerge,odul_yildiz,sira,aktif) VALUES ('turkce_zit_anlam','turkce_zit_anlam_a01','mini_uygulama','Zıt Anlamlı Kelimeler: Hadi Deneyelim','büyük-küçük ve uzun-kısa ile ilgili iki küçük örnek bul ve yüksek sesle anlat.',1,1,1) ON DUPLICATE KEY UPDATE tur=VALUES(tur),baslik=VALUES(baslik),yonerge=VALUES(yonerge),odul_yildiz=VALUES(odul_yildiz),sira=VALUES(sira),aktif=1;
INSERT INTO etkinlikler (konu_kodu,kod,tur,baslik,yonerge,odul_yildiz,sira,aktif) VALUES ('turkce_zit_anlam','turkce_zit_anlam_a02','oyun','Zıt Anlamlı Kelimeler: Mini Oyun','hızlı-yavaş, açık-kapalı ve sıcak-soğuk kavramlarından birini seç. Evde ya da sınıfta buna uygun bir örnek bul.',2,2,1) ON DUPLICATE KEY UPDATE tur=VALUES(tur),baslik=VALUES(baslik),yonerge=VALUES(yonerge),odul_yildiz=VALUES(odul_yildiz),sira=VALUES(sira),aktif=1;
INSERT INTO konular (ders_kodu,kod,ad,aciklama,sira,aktif) VALUES ('turkce','turkce_es_anlam','Yakın Anlamlı Kelimeler','Yakın Anlamlı Kelimeler konusunda 1. sınıf seviyesinde temel kazanımlar ve uygulamalar.',8,1) ON DUPLICATE KEY UPDATE ad=VALUES(ad),aciklama=VALUES(aciklama),sira=VALUES(sira),aktif=1;
INSERT INTO ders_icerikleri (konu_kodu,kod,baslik,alt_baslik,icerik,ornek_metni,sira,aktif) VALUES ('turkce_es_anlam','turkce_es_anlam_c01','Keşfedelim','Yakın Anlamlı Kelimeler','Bugün Yakın Anlamlı Kelimeler konusuna giriş yapıyoruz. cevap-yanıt ile başlayalım.','Örnek: cevap-yanıt ile ilgili bir örneği birlikte inceleyelim.',1,1) ON DUPLICATE KEY UPDATE baslik=VALUES(baslik),alt_baslik=VALUES(alt_baslik),icerik=VALUES(icerik),ornek_metni=VALUES(ornek_metni),sira=VALUES(sira),aktif=1;
INSERT INTO ders_icerikleri (konu_kodu,kod,baslik,alt_baslik,icerik,ornek_metni,sira,aktif) VALUES ('turkce_es_anlam','turkce_es_anlam_c02','Birlikte Öğrenelim','Yakın Anlamlı Kelimeler','misafir-konuk kavramını kısa bir örnekle öğrenelim ve günlük hayatta nerede kullandığımızı düşünelim.','Örnek: misafir-konuk ile ilgili bir örneği birlikte inceleyelim.',2,1) ON DUPLICATE KEY UPDATE baslik=VALUES(baslik),alt_baslik=VALUES(alt_baslik),icerik=VALUES(icerik),ornek_metni=VALUES(ornek_metni),sira=VALUES(sira),aktif=1;
INSERT INTO ders_icerikleri (konu_kodu,kod,baslik,alt_baslik,icerik,ornek_metni,sira,aktif) VALUES ('turkce_es_anlam','turkce_es_anlam_c03','Hadi Deneyelim','Yakın Anlamlı Kelimeler','Yakın Anlamlı Kelimeler konusunda küçük bir uygulama yapalım. Önce örneği incele, sonra sen dene.','Örnek: sene-yıl ile ilgili bir örneği birlikte inceleyelim.',3,1) ON DUPLICATE KEY UPDATE baslik=VALUES(baslik),alt_baslik=VALUES(alt_baslik),icerik=VALUES(icerik),ornek_metni=VALUES(ornek_metni),sira=VALUES(sira),aktif=1;
INSERT INTO ders_icerikleri (konu_kodu,kod,baslik,alt_baslik,icerik,ornek_metni,sira,aktif) VALUES ('turkce_es_anlam','turkce_es_anlam_c04','Düşün ve Söyle','Yakın Anlamlı Kelimeler','kalp-yürek ile ilgili kendi örneğini bul. Neden böyle düşündüğünü bir cümleyle anlat.','Örnek: kalp-yürek ile ilgili bir örneği birlikte inceleyelim.',4,1) ON DUPLICATE KEY UPDATE baslik=VALUES(baslik),alt_baslik=VALUES(alt_baslik),icerik=VALUES(icerik),ornek_metni=VALUES(ornek_metni),sira=VALUES(sira),aktif=1;
INSERT INTO ders_icerikleri (konu_kodu,kod,baslik,alt_baslik,icerik,ornek_metni,sira,aktif) VALUES ('turkce_es_anlam','turkce_es_anlam_c05','Mini Tekrar','Yakın Anlamlı Kelimeler','Bugün öğrendiğimiz Yakın Anlamlı Kelimeler bilgisini tekrar ediyoruz. En önemli ipucu: öykü-hikâye.','Örnek: öykü-hikâye ile ilgili bir örneği birlikte inceleyelim.',5,1) ON DUPLICATE KEY UPDATE baslik=VALUES(baslik),alt_baslik=VALUES(alt_baslik),icerik=VALUES(icerik),ornek_metni=VALUES(ornek_metni),sira=VALUES(sira),aktif=1;
