INSERT INTO konular (ders_kodu,kod,ad,aciklama,sira,aktif) VALUES ('turkce','turkce_hikaye','Kısa Hikâyeler','Kısa Hikâyeler konusunda 1. sınıf seviyesinde temel kazanımlar ve uygulamalar.',9,1) ON DUPLICATE KEY UPDATE ad=VALUES(ad),aciklama=VALUES(aciklama),sira=VALUES(sira),aktif=1;
INSERT INTO ders_icerikleri (konu_kodu,kod,baslik,alt_baslik,icerik,ornek_metni,sira,aktif) VALUES ('turkce_hikaye','turkce_hikaye_c01','Keşfedelim','Kısa Hikâyeler','Bugün Kısa Hikâyeler konusuna giriş yapıyoruz. başlangıç ile başlayalım.','Örnek: başlangıç ile ilgili bir örneği birlikte inceleyelim.',1,1) ON DUPLICATE KEY UPDATE baslik=VALUES(baslik),alt_baslik=VALUES(alt_baslik),icerik=VALUES(icerik),ornek_metni=VALUES(ornek_metni),sira=VALUES(sira),aktif=1;
INSERT INTO ders_icerikleri (konu_kodu,kod,baslik,alt_baslik,icerik,ornek_metni,sira,aktif) VALUES ('turkce_hikaye','turkce_hikaye_c02','Birlikte Öğrenelim','Kısa Hikâyeler','olay kavramını kısa bir örnekle öğrenelim ve günlük hayatta nerede kullandığımızı düşünelim.','Örnek: olay ile ilgili bir örneği birlikte inceleyelim.',2,1) ON DUPLICATE KEY UPDATE baslik=VALUES(baslik),alt_baslik=VALUES(alt_baslik),icerik=VALUES(icerik),ornek_metni=VALUES(ornek_metni),sira=VALUES(sira),aktif=1;
INSERT INTO ders_icerikleri (konu_kodu,kod,baslik,alt_baslik,icerik,ornek_metni,sira,aktif) VALUES ('turkce_hikaye','turkce_hikaye_c03','Hadi Deneyelim','Kısa Hikâyeler','Kısa Hikâyeler konusunda küçük bir uygulama yapalım. Önce örneği incele, sonra sen dene.','Örnek: karakter ile ilgili bir örneği birlikte inceleyelim.',3,1) ON DUPLICATE KEY UPDATE baslik=VALUES(baslik),alt_baslik=VALUES(alt_baslik),icerik=VALUES(icerik),ornek_metni=VALUES(ornek_metni),sira=VALUES(sira),aktif=1;
INSERT INTO ders_icerikleri (konu_kodu,kod,baslik,alt_baslik,icerik,ornek_metni,sira,aktif) VALUES ('turkce_hikaye','turkce_hikaye_c04','Düşün ve Söyle','Kısa Hikâyeler','yer ile ilgili kendi örneğini bul. Neden böyle düşündüğünü bir cümleyle anlat.','Örnek: yer ile ilgili bir örneği birlikte inceleyelim.',4,1) ON DUPLICATE KEY UPDATE baslik=VALUES(baslik),alt_baslik=VALUES(alt_baslik),icerik=VALUES(icerik),ornek_metni=VALUES(ornek_metni),sira=VALUES(sira),aktif=1;
INSERT INTO ders_icerikleri (konu_kodu,kod,baslik,alt_baslik,icerik,ornek_metni,sira,aktif) VALUES ('turkce_hikaye','turkce_hikaye_c05','Mini Tekrar','Kısa Hikâyeler','Bugün öğrendiğimiz Kısa Hikâyeler bilgisini tekrar ediyoruz. En önemli ipucu: sonuç.','Örnek: sonuç ile ilgili bir örneği birlikte inceleyelim.',5,1) ON DUPLICATE KEY UPDATE baslik=VALUES(baslik),alt_baslik=VALUES(alt_baslik),icerik=VALUES(icerik),ornek_metni=VALUES(ornek_metni),sira=VALUES(sira),aktif=1;
INSERT INTO sorular (konu_kodu,kod,soru_turu,soru,secenekler_json,dogru_cevap,aciklama,zorluk,sira,aktif) VALUES ('turkce_hikaye','turkce_hikaye_q01','coktan_secmeli','Kısa Hikâyeler konusunda ilk öğrendiğimiz kavram hangisidir?','["başlangıç","olay","karakter","rastgele"]','başlangıç','Bu konuda temel kavramlardan biri başlangıç.',1,1,1) ON DUPLICATE KEY UPDATE soru=VALUES(soru),secenekler_json=VALUES(secenekler_json),dogru_cevap=VALUES(dogru_cevap),aciklama=VALUES(aciklama),zorluk=VALUES(zorluk),sira=VALUES(sira),aktif=1;
INSERT INTO sorular (konu_kodu,kod,soru_turu,soru,secenekler_json,dogru_cevap,aciklama,zorluk,sira,aktif) VALUES ('turkce_hikaye','turkce_hikaye_q02','coktan_secmeli','Kısa Hikâyeler ile ilgili doğru seçeneği bul.','["olay","ilgisiz cevap","yanlış seçenek","hiçbiri"]','olay','olay bu konunun içindedir.',1,2,1) ON DUPLICATE KEY UPDATE soru=VALUES(soru),secenekler_json=VALUES(secenekler_json),dogru_cevap=VALUES(dogru_cevap),aciklama=VALUES(aciklama),zorluk=VALUES(zorluk),sira=VALUES(sira),aktif=1;
INSERT INTO sorular (konu_kodu,kod,soru_turu,soru,secenekler_json,dogru_cevap,aciklama,zorluk,sira,aktif) VALUES ('turkce_hikaye','turkce_hikaye_q03','coktan_secmeli','Aşağıdakilerden hangisi Kısa Hikâyeler ile ilişkilidir?','["karakter","uzay roketi","bilgisayar oyunu","trafik cezası"]','karakter','karakter bu konuyla ilişkilidir.',1,3,1) ON DUPLICATE KEY UPDATE soru=VALUES(soru),secenekler_json=VALUES(secenekler_json),dogru_cevap=VALUES(dogru_cevap),aciklama=VALUES(aciklama),zorluk=VALUES(zorluk),sira=VALUES(sira),aktif=1;
INSERT INTO sorular (konu_kodu,kod,soru_turu,soru,secenekler_json,dogru_cevap,aciklama,zorluk,sira,aktif) VALUES ('turkce_hikaye','turkce_hikaye_q04','coktan_secmeli','Yer bu konunun bir parçasıdır. Doğru mu?','["Evet","Hayır","Bazen","Bilinmez"]','Evet','Evet, yer bu konunun içinde yer alır.',1,4,1) ON DUPLICATE KEY UPDATE soru=VALUES(soru),secenekler_json=VALUES(secenekler_json),dogru_cevap=VALUES(dogru_cevap),aciklama=VALUES(aciklama),zorluk=VALUES(zorluk),sira=VALUES(sira),aktif=1;
INSERT INTO sorular (konu_kodu,kod,soru_turu,soru,secenekler_json,dogru_cevap,aciklama,zorluk,sira,aktif) VALUES ('turkce_hikaye','turkce_hikaye_q05','coktan_secmeli','Hangisi Kısa Hikâyeler için uygun bir örnektir?','["sonuç","uygunsuz davranış","konu dışı örnek","hiçbiri"]','sonuç','sonuç uygun bir örnektir.',2,5,1) ON DUPLICATE KEY UPDATE soru=VALUES(soru),secenekler_json=VALUES(secenekler_json),dogru_cevap=VALUES(dogru_cevap),aciklama=VALUES(aciklama),zorluk=VALUES(zorluk),sira=VALUES(sira),aktif=1;
INSERT INTO sorular (konu_kodu,kod,soru_turu,soru,secenekler_json,dogru_cevap,aciklama,zorluk,sira,aktif) VALUES ('turkce_hikaye','turkce_hikaye_q06','coktan_secmeli','başlangıç ile olay birlikte hangi başlıkta öğrenilir?','["Kısa Hikâyeler","Başka bir konu","Sadece oyun","Hiçbiri"]','Kısa Hikâyeler','İkisi de Kısa Hikâyeler başlığında öğrenilir.',2,6,1) ON DUPLICATE KEY UPDATE soru=VALUES(soru),secenekler_json=VALUES(secenekler_json),dogru_cevap=VALUES(dogru_cevap),aciklama=VALUES(aciklama),zorluk=VALUES(zorluk),sira=VALUES(sira),aktif=1;
INSERT INTO sorular (konu_kodu,kod,soru_turu,soru,secenekler_json,dogru_cevap,aciklama,zorluk,sira,aktif) VALUES ('turkce_hikaye','turkce_hikaye_q07','coktan_secmeli','Kısa Hikâyeler öğrenirken ilk ne yapmalıyız?','["Örneği incelemek","Rastgele seçmek","Atlamak","Hiç bakmamak"]','Örneği incelemek','Örneği incelemek öğrenmeyi kolaylaştırır.',2,7,1) ON DUPLICATE KEY UPDATE soru=VALUES(soru),secenekler_json=VALUES(secenekler_json),dogru_cevap=VALUES(dogru_cevap),aciklama=VALUES(aciklama),zorluk=VALUES(zorluk),sira=VALUES(sira),aktif=1;
INSERT INTO sorular (konu_kodu,kod,soru_turu,soru,secenekler_json,dogru_cevap,aciklama,zorluk,sira,aktif) VALUES ('turkce_hikaye','turkce_hikaye_q08','coktan_secmeli','karakter hakkında öğrendiğimizi nasıl gösteririz?','["Doğru örnek vererek","Konuyu değiştirerek","Tahmin etmeden","Bakmadan"]','Doğru örnek vererek','Doğru örnek vermek bilgimizi gösterir.',2,8,1) ON DUPLICATE KEY UPDATE soru=VALUES(soru),secenekler_json=VALUES(secenekler_json),dogru_cevap=VALUES(dogru_cevap),aciklama=VALUES(aciklama),zorluk=VALUES(zorluk),sira=VALUES(sira),aktif=1;
