INSERT INTO ders_icerikleri (konu_kodu,kod,baslik,alt_baslik,icerik,ornek_metni,sira,aktif) VALUES ('hayat_bilgisi_saglik','hayat_bilgisi_saglik_c05','Mini Tekrar','Sağlıklı Yaşam','Bugün öğrendiğimiz Sağlıklı Yaşam bilgisini tekrar ediyoruz. En önemli ipucu: hareket.','Örnek: hareket ile ilgili bir örneği birlikte inceleyelim.',5,1) ON DUPLICATE KEY UPDATE baslik=VALUES(baslik),alt_baslik=VALUES(alt_baslik),icerik=VALUES(icerik),ornek_metni=VALUES(ornek_metni),sira=VALUES(sira),aktif=1;
INSERT INTO sorular (konu_kodu,kod,soru_turu,soru,secenekler_json,dogru_cevap,aciklama,zorluk,sira,aktif) VALUES ('hayat_bilgisi_saglik','hayat_bilgisi_saglik_q01','coktan_secmeli','Sağlıklı Yaşam konusunda ilk öğrendiğimiz kavram hangisidir?','["el yıkama","diş fırçalama","uyku","rastgele"]','el yıkama','Bu konuda temel kavramlardan biri el yıkama.',1,1,1) ON DUPLICATE KEY UPDATE soru=VALUES(soru),secenekler_json=VALUES(secenekler_json),dogru_cevap=VALUES(dogru_cevap),aciklama=VALUES(aciklama),zorluk=VALUES(zorluk),sira=VALUES(sira),aktif=1;
INSERT INTO sorular (konu_kodu,kod,soru_turu,soru,secenekler_json,dogru_cevap,aciklama,zorluk,sira,aktif) VALUES ('hayat_bilgisi_saglik','hayat_bilgisi_saglik_q02','coktan_secmeli','Sağlıklı Yaşam ile ilgili doğru seçeneği bul.','["diş fırçalama","ilgisiz cevap","yanlış seçenek","hiçbiri"]','diş fırçalama','diş fırçalama bu konunun içindedir.',1,2,1) ON DUPLICATE KEY UPDATE soru=VALUES(soru),secenekler_json=VALUES(secenekler_json),dogru_cevap=VALUES(dogru_cevap),aciklama=VALUES(aciklama),zorluk=VALUES(zorluk),sira=VALUES(sira),aktif=1;
