INSERT INTO sorular (konu_kodu,kod,soru_turu,soru,secenekler_json,dogru_cevap,aciklama,zorluk,sira,aktif) VALUES ('hayat_bilgisi_saglik','hayat_bilgisi_saglik_q06','coktan_secmeli','el yıkama ile diş fırçalama birlikte hangi başlıkta öğrenilir?','["Sağlıklı Yaşam","Başka bir konu","Sadece oyun","Hiçbiri"]','Sağlıklı Yaşam','İkisi de Sağlıklı Yaşam başlığında öğrenilir.',2,6,1) ON DUPLICATE KEY UPDATE soru=VALUES(soru),secenekler_json=VALUES(secenekler_json),dogru_cevap=VALUES(dogru_cevap),aciklama=VALUES(aciklama),zorluk=VALUES(zorluk),sira=VALUES(sira),aktif=1;
