INSERT INTO ders_icerikleri (konu_kodu,kod,baslik,alt_baslik,icerik,ornek_metni,sira,aktif) VALUES ('hayat_bilgisi_trafik','hayat_bilgisi_trafik_c01','Keşfedelim','Trafik ve Yaya Güvenliği','Bugün Trafik ve Yaya Güvenliği konusuna giriş yapıyoruz. yaya geçidi ile başlayalım.','Örnek: yaya geçidi ile ilgili bir örneği birlikte inceleyelim.',1,1) ON DUPLICATE KEY UPDATE baslik=VALUES(baslik),alt_baslik=VALUES(alt_baslik),icerik=VALUES(icerik),ornek_metni=VALUES(ornek_metni),sira=VALUES(sira),aktif=1;
