INSERT INTO sorular (konu_kodu,kod,soru_turu,soru,secenekler_json,dogru_cevap,aciklama,zorluk,sira,aktif) VALUES ('hayat_bilgisi_doga','hayat_bilgisi_doga_q01','coktan_secmeli','Doğa ve Çevre konusunda ilk öğrendiğimiz kavram hangisidir?','["bitki","hayvan","geri dönüşüm","rastgele"]','bitki','Bu konuda temel kavramlardan biri bitki.',1,1,1) ON DUPLICATE KEY UPDATE soru=VALUES(soru),secenekler_json=VALUES(secenekler_json),dogru_cevap=VALUES(dogru_cevap),aciklama=VALUES(aciklama),zorluk=VALUES(zorluk),sira=VALUES(sira),aktif=1;
