INSERT INTO sorular (konu_kodu,kod,soru_turu,soru,secenekler_json,dogru_cevap,aciklama,zorluk,sira,aktif) VALUES ('hayat_bilgisi_doga','hayat_bilgisi_doga_q03','coktan_secmeli','Aşağıdakilerden hangisi Doğa ve Çevre ile ilişkilidir?','["geri dönüşüm","uzay roketi","bilgisayar oyunu","trafik cezası"]','geri dönüşüm','geri dönüşüm bu konuyla ilişkilidir.',1,3,1) ON DUPLICATE KEY UPDATE soru=VALUES(soru),secenekler_json=VALUES(secenekler_json),dogru_cevap=VALUES(dogru_cevap),aciklama=VALUES(aciklama),zorluk=VALUES(zorluk),sira=VALUES(sira),aktif=1;
