INSERT INTO sorular (konu_kodu,kod,soru_turu,soru,secenekler_json,dogru_cevap,aciklama,zorluk,sira,aktif) VALUES ('hayat_bilgisi_doga','hayat_bilgisi_doga_q05','coktan_secmeli','Hangisi Doğa ve Çevre için uygun bir örnektir?','["çevre temizliği","uygunsuz davranış","konu dışı örnek","hiçbiri"]','çevre temizliği','çevre temizliği uygun bir örnektir.',2,5,1) ON DUPLICATE KEY UPDATE soru=VALUES(soru),secenekler_json=VALUES(secenekler_json),dogru_cevap=VALUES(dogru_cevap),aciklama=VALUES(aciklama),zorluk=VALUES(zorluk),sira=VALUES(sira),aktif=1;
