INSERT INTO ders_icerikleri (konu_kodu,kod,baslik,alt_baslik,icerik,ornek_metni,sira,aktif) VALUES ('gorsel_sanatlar_renkler','gorsel_sanatlar_renkler_c01','Keşfedelim','Renkler','Bugün Renkler konusuna giriş yapıyoruz. ana renk ile başlayalım.','Örnek: ana renk ile ilgili bir örneği birlikte inceleyelim.',1,1) ON DUPLICATE KEY UPDATE baslik=VALUES(baslik),alt_baslik=VALUES(alt_baslik),icerik=VALUES(icerik),ornek_metni=VALUES(ornek_metni),sira=VALUES(sira),aktif=1;
