INSERT INTO etkinlikler (konu_kodu,kod,tur,baslik,yonerge,odul_yildiz,sira,aktif) VALUES ('gorsel_sanatlar_cizgiler','gorsel_sanatlar_cizgiler_a01','mini_uygulama','Çizgiler: Hadi Deneyelim','düz ve eğri ile ilgili iki küçük örnek bul ve yüksek sesle anlat.',1,1,1) ON DUPLICATE KEY UPDATE tur=VALUES(tur),baslik=VALUES(baslik),yonerge=VALUES(yonerge),odul_yildiz=VALUES(odul_yildiz),sira=VALUES(sira),aktif=1;
