INSERT INTO konular (ders_kodu,kod,ad,aciklama,sira,aktif) VALUES ('gorsel_sanatlar','gorsel_sanatlar_sekiller','Şekillerle Resim','Şekillerle Resim konusunda 1. sınıf seviyesinde temel kazanımlar ve uygulamalar.',3,1) ON DUPLICATE KEY UPDATE ad=VALUES(ad),aciklama=VALUES(aciklama),sira=VALUES(sira),aktif=1;
INSERT INTO ders_icerikleri (konu_kodu,kod,baslik,alt_baslik,icerik,ornek_metni,sira,aktif) VALUES ('gorsel_sanatlar_sekiller','gorsel_sanatlar_sekiller_c01','Keşfedelim','Şekillerle Resim','Bugün Şekillerle Resim konusuna giriş yapıyoruz. daire ile başlayalım.','Örnek: daire ile ilgili bir örneği birlikte inceleyelim.',1,1) ON DUPLICATE KEY UPDATE baslik=VALUES(baslik),alt_baslik=VALUES(alt_baslik),icerik=VALUES(icerik),ornek_metni=VALUES(ornek_metni),sira=VALUES(sira),aktif=1;
INSERT INTO ders_icerikleri (konu_kodu,kod,baslik,alt_baslik,icerik,ornek_metni,sira,aktif) VALUES ('gorsel_sanatlar_sekiller','gorsel_sanatlar_sekiller_c02','Birlikte Öğrenelim','Şekillerle Resim','üçgen kavramını kısa bir örnekle öğrenelim ve günlük hayatta nerede kullandığımızı düşünelim.','Örnek: üçgen ile ilgili bir örneği birlikte inceleyelim.',2,1) ON DUPLICATE KEY UPDATE baslik=VALUES(baslik),alt_baslik=VALUES(alt_baslik),icerik=VALUES(icerik),ornek_metni=VALUES(ornek_metni),sira=VALUES(sira),aktif=1;
INSERT INTO ders_icerikleri (konu_kodu,kod,baslik,alt_baslik,icerik,ornek_metni,sira,aktif) VALUES ('gorsel_sanatlar_sekiller','gorsel_sanatlar_sekiller_c03','Hadi Deneyelim','Şekillerle Resim','Şekillerle Resim konusunda küçük bir uygulama yapalım. Önce örneği incele, sonra sen dene.','Örnek: kare ile ilgili bir örneği birlikte inceleyelim.',3,1) ON DUPLICATE KEY UPDATE baslik=VALUES(baslik),alt_baslik=VALUES(alt_baslik),icerik=VALUES(icerik),ornek_metni=VALUES(ornek_metni),sira=VALUES(sira),aktif=1;
INSERT INTO ders_icerikleri (konu_kodu,kod,baslik,alt_baslik,icerik,ornek_metni,sira,aktif) VALUES ('gorsel_sanatlar_sekiller','gorsel_sanatlar_sekiller_c04','Düşün ve Söyle','Şekillerle Resim','dikdörtgen ile ilgili kendi örneğini bul. Neden böyle düşündüğünü bir cümleyle anlat.','Örnek: dikdörtgen ile ilgili bir örneği birlikte inceleyelim.',4,1) ON DUPLICATE KEY UPDATE baslik=VALUES(baslik),alt_baslik=VALUES(alt_baslik),icerik=VALUES(icerik),ornek_metni=VALUES(ornek_metni),sira=VALUES(sira),aktif=1;
INSERT INTO ders_icerikleri (konu_kodu,kod,baslik,alt_baslik,icerik,ornek_metni,sira,aktif) VALUES ('gorsel_sanatlar_sekiller','gorsel_sanatlar_sekiller_c05','Mini Tekrar','Şekillerle Resim','Bugün öğrendiğimiz Şekillerle Resim bilgisini tekrar ediyoruz. En önemli ipucu: şekil birleştirme.','Örnek: şekil birleştirme ile ilgili bir örneği birlikte inceleyelim.',5,1) ON DUPLICATE KEY UPDATE baslik=VALUES(baslik),alt_baslik=VALUES(alt_baslik),icerik=VALUES(icerik),ornek_metni=VALUES(ornek_metni),sira=VALUES(sira),aktif=1;
