INSERT INTO konular (ders_kodu,kod,ad,aciklama,sira,aktif) VALUES ('gorsel_sanatlar','gorsel_sanatlar_desenler','Desen ve Tekrar','Desen ve Tekrar konusunda 1. sınıf seviyesinde temel kazanımlar ve uygulamalar.',4,1) ON DUPLICATE KEY UPDATE ad=VALUES(ad),aciklama=VALUES(aciklama),sira=VALUES(sira),aktif=1;
