INSERT INTO ders_icerikleri (konu_kodu,kod,baslik,alt_baslik,icerik,ornek_metni,sira,aktif) VALUES ('gorsel_sanatlar_desenler','gorsel_sanatlar_desenler_c04','Düşün ve Söyle','Desen ve Tekrar','tekrar ile ilgili kendi örneğini bul. Neden böyle düşündüğünü bir cümleyle anlat.','Örnek: tekrar ile ilgili bir örneği birlikte inceleyelim.',4,1) ON DUPLICATE KEY UPDATE baslik=VALUES(baslik),alt_baslik=VALUES(alt_baslik),icerik=VALUES(icerik),ornek_metni=VALUES(ornek_metni),sira=VALUES(sira),aktif=1;
