INSERT INTO konular (ders_kodu,kod,ad,aciklama,sira,aktif) VALUES ('gorsel_sanatlar','gorsel_sanatlar_hayal_gucu','Hayal Gücü Çizimleri','Hayal Gücü Çizimleri konusunda 1. sınıf seviyesinde temel kazanımlar ve uygulamalar.',6,1) ON DUPLICATE KEY UPDATE ad=VALUES(ad),aciklama=VALUES(aciklama),sira=VALUES(sira),aktif=1;
