INSERT INTO ders_icerikleri (konu_kodu,kod,baslik,alt_baslik,icerik,ornek_metni,sira,aktif) VALUES ('gorsel_sanatlar_kolaj','gorsel_sanatlar_kolaj_c01','Keşfedelim','Kes-Yapıştır ve Kolaj','Bugün Kes-Yapıştır ve Kolaj konusuna giriş yapıyoruz. kâğıt ile başlayalım.','Örnek: kâğıt ile ilgili bir örneği birlikte inceleyelim.',1,1) ON DUPLICATE KEY UPDATE baslik=VALUES(baslik),alt_baslik=VALUES(alt_baslik),icerik=VALUES(icerik),ornek_metni=VALUES(ornek_metni),sira=VALUES(sira),aktif=1;
