INSERT INTO ders_icerikleri (konu_kodu,kod,baslik,alt_baslik,icerik,ornek_metni,sira,aktif) VALUES ('muzik_ses','muzik_ses_c04','Düşün ve Söyle','İnce ve Kalın Ses','alçak ile ilgili kendi örneğini bul. Neden böyle düşündüğünü bir cümleyle anlat.','Örnek: alçak ile ilgili bir örneği birlikte inceleyelim.',4,1) ON DUPLICATE KEY UPDATE baslik=VALUES(baslik),alt_baslik=VALUES(alt_baslik),icerik=VALUES(icerik),ornek_metni=VALUES(ornek_metni),sira=VALUES(sira),aktif=1;
INSERT INTO ders_icerikleri (konu_kodu,kod,baslik,alt_baslik,icerik,ornek_metni,sira,aktif) VALUES ('muzik_ses','muzik_ses_c05','Mini Tekrar','İnce ve Kalın Ses','Bugün öğrendiğimiz İnce ve Kalın Ses bilgisini tekrar ediyoruz. En önemli ipucu: dinleme.','Örnek: dinleme ile ilgili bir örneği birlikte inceleyelim.',5,1) ON DUPLICATE KEY UPDATE baslik=VALUES(baslik),alt_baslik=VALUES(alt_baslik),icerik=VALUES(icerik),ornek_metni=VALUES(ornek_metni),sira=VALUES(sira),aktif=1;
INSERT INTO sorular (konu_kodu,kod,soru_turu,soru,secenekler_json,dogru_cevap,aciklama,zorluk,sira,aktif) VALUES ('muzik_ses','muzik_ses_q01','coktan_secmeli','İnce ve Kalın Ses konusunda ilk öğrendiğimiz kavram hangisidir?','["ince ses","kalın ses","yüksek","rastgele"]','ince ses','Bu konuda temel kavramlardan biri ince ses.',1,1,1) ON DUPLICATE KEY UPDATE soru=VALUES(soru),secenekler_json=VALUES(secenekler_json),dogru_cevap=VALUES(dogru_cevap),aciklama=VALUES(aciklama),zorluk=VALUES(zorluk),sira=VALUES(sira),aktif=1;
