INSERT INTO sorular (konu_kodu,kod,soru_turu,soru,secenekler_json,dogru_cevap,aciklama,zorluk,sira,aktif) VALUES ('muzik_ses','muzik_ses_q06','coktan_secmeli','ince ses ile kalın ses birlikte hangi başlıkta öğrenilir?','["İnce ve Kalın Ses","Başka bir konu","Sadece oyun","Hiçbiri"]','İnce ve Kalın Ses','İkisi de İnce ve Kalın Ses başlığında öğrenilir.',2,6,1) ON DUPLICATE KEY UPDATE soru=VALUES(soru),secenekler_json=VALUES(secenekler_json),dogru_cevap=VALUES(dogru_cevap),aciklama=VALUES(aciklama),zorluk=VALUES(zorluk),sira=VALUES(sira),aktif=1;
INSERT INTO sorular (konu_kodu,kod,soru_turu,soru,secenekler_json,dogru_cevap,aciklama,zorluk,sira,aktif) VALUES ('muzik_ses','muzik_ses_q07','coktan_secmeli','İnce ve Kalın Ses öğrenirken ilk ne yapmalıyız?','["Örneği incelemek","Rastgele seçmek","Atlamak","Hiç bakmamak"]','Örneği incelemek','Örneği incelemek öğrenmeyi kolaylaştırır.',2,7,1) ON DUPLICATE KEY UPDATE soru=VALUES(soru),secenekler_json=VALUES(secenekler_json),dogru_cevap=VALUES(dogru_cevap),aciklama=VALUES(aciklama),zorluk=VALUES(zorluk),sira=VALUES(sira),aktif=1;
