INSERT INTO konular (ders_kodu,kod,ad,aciklama,sira,aktif) VALUES ('muzik','muzik_enstruman','Çalgıları Tanıyorum','Çalgıları Tanıyorum konusunda 1. sınıf seviyesinde temel kazanımlar ve uygulamalar.',5,1) ON DUPLICATE KEY UPDATE ad=VALUES(ad),aciklama=VALUES(aciklama),sira=VALUES(sira),aktif=1;
INSERT INTO ders_icerikleri (konu_kodu,kod,baslik,alt_baslik,icerik,ornek_metni,sira,aktif) VALUES ('muzik_enstruman','muzik_enstruman_c01','Keşfedelim','Çalgıları Tanıyorum','Bugün Çalgıları Tanıyorum konusuna giriş yapıyoruz. davul ile başlayalım.','Örnek: davul ile ilgili bir örneği birlikte inceleyelim.',1,1) ON DUPLICATE KEY UPDATE baslik=VALUES(baslik),alt_baslik=VALUES(alt_baslik),icerik=VALUES(icerik),ornek_metni=VALUES(ornek_metni),sira=VALUES(sira),aktif=1;
INSERT INTO ders_icerikleri (konu_kodu,kod,baslik,alt_baslik,icerik,ornek_metni,sira,aktif) VALUES ('muzik_enstruman','muzik_enstruman_c02','Birlikte Öğrenelim','Çalgıları Tanıyorum','flüt kavramını kısa bir örnekle öğrenelim ve günlük hayatta nerede kullandığımızı düşünelim.','Örnek: flüt ile ilgili bir örneği birlikte inceleyelim.',2,1) ON DUPLICATE KEY UPDATE baslik=VALUES(baslik),alt_baslik=VALUES(alt_baslik),icerik=VALUES(icerik),ornek_metni=VALUES(ornek_metni),sira=VALUES(sira),aktif=1;
INSERT INTO ders_icerikleri (konu_kodu,kod,baslik,alt_baslik,icerik,ornek_metni,sira,aktif) VALUES ('muzik_enstruman','muzik_enstruman_c03','Hadi Deneyelim','Çalgıları Tanıyorum','Çalgıları Tanıyorum konusunda küçük bir uygulama yapalım. Önce örneği incele, sonra sen dene.','Örnek: piyano ile ilgili bir örneği birlikte inceleyelim.',3,1) ON DUPLICATE KEY UPDATE baslik=VALUES(baslik),alt_baslik=VALUES(alt_baslik),icerik=VALUES(icerik),ornek_metni=VALUES(ornek_metni),sira=VALUES(sira),aktif=1;
INSERT INTO ders_icerikleri (konu_kodu,kod,baslik,alt_baslik,icerik,ornek_metni,sira,aktif) VALUES ('muzik_enstruman','muzik_enstruman_c04','Düşün ve Söyle','Çalgıları Tanıyorum','gitar ile ilgili kendi örneğini bul. Neden böyle düşündüğünü bir cümleyle anlat.','Örnek: gitar ile ilgili bir örneği birlikte inceleyelim.',4,1) ON DUPLICATE KEY UPDATE baslik=VALUES(baslik),alt_baslik=VALUES(alt_baslik),icerik=VALUES(icerik),ornek_metni=VALUES(ornek_metni),sira=VALUES(sira),aktif=1;
