INSERT INTO sorular (konu_kodu,kod,soru_turu,soru,secenekler_json,dogru_cevap,aciklama,zorluk,sira,aktif) VALUES ('muzik_sarki','muzik_sarki_q02','coktan_secmeli','Şarkı Söyleme ile ilgili doğru seçeneği bul.','["birlikte söyleme","ilgisiz cevap","yanlış seçenek","hiçbiri"]','birlikte söyleme','birlikte söyleme bu konunun içindedir.',1,2,1) ON DUPLICATE KEY UPDATE soru=VALUES(soru),secenekler_json=VALUES(secenekler_json),dogru_cevap=VALUES(dogru_cevap),aciklama=VALUES(aciklama),zorluk=VALUES(zorluk),sira=VALUES(sira),aktif=1;
