INSERT INTO ders_icerikleri (konu_kodu,kod,baslik,alt_baslik,icerik,ornek_metni,sira,aktif) VALUES ('beden_sicrama','beden_sicrama_c03','Hadi Deneyelim','Sıçrama ve Atlama','Sıçrama ve Atlama konusunda küçük bir uygulama yapalım. Önce örneği incele, sonra sen dene.','Örnek: ileri atlama ile ilgili bir örneği birlikte inceleyelim.',3,1) ON DUPLICATE KEY UPDATE baslik=VALUES(baslik),alt_baslik=VALUES(alt_baslik),icerik=VALUES(icerik),ornek_metni=VALUES(ornek_metni),sira=VALUES(sira),aktif=1;
INSERT INTO ders_icerikleri (konu_kodu,kod,baslik,alt_baslik,icerik,ornek_metni,sira,aktif) VALUES ('beden_sicrama','beden_sicrama_c04','Düşün ve Söyle','Sıçrama ve Atlama','çizgi atlama ile ilgili kendi örneğini bul. Neden böyle düşündüğünü bir cümleyle anlat.','Örnek: çizgi atlama ile ilgili bir örneği birlikte inceleyelim.',4,1) ON DUPLICATE KEY UPDATE baslik=VALUES(baslik),alt_baslik=VALUES(alt_baslik),icerik=VALUES(icerik),ornek_metni=VALUES(ornek_metni),sira=VALUES(sira),aktif=1;
INSERT INTO ders_icerikleri (konu_kodu,kod,baslik,alt_baslik,icerik,ornek_metni,sira,aktif) VALUES ('beden_sicrama','beden_sicrama_c05','Mini Tekrar','Sıçrama ve Atlama','Bugün öğrendiğimiz Sıçrama ve Atlama bilgisini tekrar ediyoruz. En önemli ipucu: güvenli iniş.','Örnek: güvenli iniş ile ilgili bir örneği birlikte inceleyelim.',5,1) ON DUPLICATE KEY UPDATE baslik=VALUES(baslik),alt_baslik=VALUES(alt_baslik),icerik=VALUES(icerik),ornek_metni=VALUES(ornek_metni),sira=VALUES(sira),aktif=1;
INSERT INTO sorular (konu_kodu,kod,soru_turu,soru,secenekler_json,dogru_cevap,aciklama,zorluk,sira,aktif) VALUES ('beden_sicrama','beden_sicrama_q01','coktan_secmeli','Sıçrama ve Atlama konusunda ilk öğrendiğimiz kavram hangisidir?','["çift ayak","tek ayak","ileri atlama","rastgele"]','çift ayak','Bu konuda temel kavramlardan biri çift ayak.',1,1,1) ON DUPLICATE KEY UPDATE soru=VALUES(soru),secenekler_json=VALUES(secenekler_json),dogru_cevap=VALUES(dogru_cevap),aciklama=VALUES(aciklama),zorluk=VALUES(zorluk),sira=VALUES(sira),aktif=1;
INSERT INTO sorular (konu_kodu,kod,soru_turu,soru,secenekler_json,dogru_cevap,aciklama,zorluk,sira,aktif) VALUES ('beden_sicrama','beden_sicrama_q02','coktan_secmeli','Sıçrama ve Atlama ile ilgili doğru seçeneği bul.','["tek ayak","ilgisiz cevap","yanlış seçenek","hiçbiri"]','tek ayak','tek ayak bu konunun içindedir.',1,2,1) ON DUPLICATE KEY UPDATE soru=VALUES(soru),secenekler_json=VALUES(secenekler_json),dogru_cevap=VALUES(dogru_cevap),aciklama=VALUES(aciklama),zorluk=VALUES(zorluk),sira=VALUES(sira),aktif=1;
INSERT INTO sorular (konu_kodu,kod,soru_turu,soru,secenekler_json,dogru_cevap,aciklama,zorluk,sira,aktif) VALUES ('beden_sicrama','beden_sicrama_q03','coktan_secmeli','Aşağıdakilerden hangisi Sıçrama ve Atlama ile ilişkilidir?','["ileri atlama","uzay roketi","bilgisayar oyunu","trafik cezası"]','ileri atlama','ileri atlama bu konuyla ilişkilidir.',1,3,1) ON DUPLICATE KEY UPDATE soru=VALUES(soru),secenekler_json=VALUES(secenekler_json),dogru_cevap=VALUES(dogru_cevap),aciklama=VALUES(aciklama),zorluk=VALUES(zorluk),sira=VALUES(sira),aktif=1;
INSERT INTO sorular (konu_kodu,kod,soru_turu,soru,secenekler_json,dogru_cevap,aciklama,zorluk,sira,aktif) VALUES ('beden_sicrama','beden_sicrama_q04','coktan_secmeli','Çizgi atlama bu konunun bir parçasıdır. Doğru mu?','["Evet","Hayır","Bazen","Bilinmez"]','Evet','Evet, çizgi atlama bu konunun içinde yer alır.',1,4,1) ON DUPLICATE KEY UPDATE soru=VALUES(soru),secenekler_json=VALUES(secenekler_json),dogru_cevap=VALUES(dogru_cevap),aciklama=VALUES(aciklama),zorluk=VALUES(zorluk),sira=VALUES(sira),aktif=1;
INSERT INTO sorular (konu_kodu,kod,soru_turu,soru,secenekler_json,dogru_cevap,aciklama,zorluk,sira,aktif) VALUES ('beden_sicrama','beden_sicrama_q05','coktan_secmeli','Hangisi Sıçrama ve Atlama için uygun bir örnektir?','["güvenli iniş","uygunsuz davranış","konu dışı örnek","hiçbiri"]','güvenli iniş','güvenli iniş uygun bir örnektir.',2,5,1) ON DUPLICATE KEY UPDATE soru=VALUES(soru),secenekler_json=VALUES(secenekler_json),dogru_cevap=VALUES(dogru_cevap),aciklama=VALUES(aciklama),zorluk=VALUES(zorluk),sira=VALUES(sira),aktif=1;
INSERT INTO sorular (konu_kodu,kod,soru_turu,soru,secenekler_json,dogru_cevap,aciklama,zorluk,sira,aktif) VALUES ('beden_sicrama','beden_sicrama_q06','coktan_secmeli','çift ayak ile tek ayak birlikte hangi başlıkta öğrenilir?','["Sıçrama ve Atlama","Başka bir konu","Sadece oyun","Hiçbiri"]','Sıçrama ve Atlama','İkisi de Sıçrama ve Atlama başlığında öğrenilir.',2,6,1) ON DUPLICATE KEY UPDATE soru=VALUES(soru),secenekler_json=VALUES(secenekler_json),dogru_cevap=VALUES(dogru_cevap),aciklama=VALUES(aciklama),zorluk=VALUES(zorluk),sira=VALUES(sira),aktif=1;
