INSERT INTO sorular (konu_kodu,kod,soru_turu,soru,secenekler_json,dogru_cevap,aciklama,zorluk,sira,aktif) VALUES ('beden_sicrama','beden_sicrama_q08','coktan_secmeli','ileri atlama hakkında öğrendiğimizi nasıl gösteririz?','["Doğru örnek vererek","Konuyu değiştirerek","Tahmin etmeden","Bakmadan"]','Doğru örnek vererek','Doğru örnek vermek bilgimizi gösterir.',2,8,1) ON DUPLICATE KEY UPDATE soru=VALUES(soru),secenekler_json=VALUES(secenekler_json),dogru_cevap=VALUES(dogru_cevap),aciklama=VALUES(aciklama),zorluk=VALUES(zorluk),sira=VALUES(sira),aktif=1;
