INSERT INTO konular (ders_kodu,kod,ad,aciklama,sira,aktif) VALUES ('beden','beden_kuralli_oyun','Kurallı Oyunlar','Kurallı Oyunlar konusunda 1. sınıf seviyesinde temel kazanımlar ve uygulamalar.',6,1) ON DUPLICATE KEY UPDATE ad=VALUES(ad),aciklama=VALUES(aciklama),sira=VALUES(sira),aktif=1;
INSERT INTO ders_icerikleri (konu_kodu,kod,baslik,alt_baslik,icerik,ornek_metni,sira,aktif) VALUES ('beden_kuralli_oyun','beden_kuralli_oyun_c01','Keşfedelim','Kurallı Oyunlar','Bugün Kurallı Oyunlar konusuna giriş yapıyoruz. sıra ile başlayalım.','Örnek: sıra ile ilgili bir örneği birlikte inceleyelim.',1,1) ON DUPLICATE KEY UPDATE baslik=VALUES(baslik),alt_baslik=VALUES(alt_baslik),icerik=VALUES(icerik),ornek_metni=VALUES(ornek_metni),sira=VALUES(sira),aktif=1;
INSERT INTO ders_icerikleri (konu_kodu,kod,baslik,alt_baslik,icerik,ornek_metni,sira,aktif) VALUES ('beden_kuralli_oyun','beden_kuralli_oyun_c02','Birlikte Öğrenelim','Kurallı Oyunlar','başla-dur kavramını kısa bir örnekle öğrenelim ve günlük hayatta nerede kullandığımızı düşünelim.','Örnek: başla-dur ile ilgili bir örneği birlikte inceleyelim.',2,1) ON DUPLICATE KEY UPDATE baslik=VALUES(baslik),alt_baslik=VALUES(alt_baslik),icerik=VALUES(icerik),ornek_metni=VALUES(ornek_metni),sira=VALUES(sira),aktif=1;
INSERT INTO ders_icerikleri (konu_kodu,kod,baslik,alt_baslik,icerik,ornek_metni,sira,aktif) VALUES ('beden_kuralli_oyun','beden_kuralli_oyun_c03','Hadi Deneyelim','Kurallı Oyunlar','Kurallı Oyunlar konusunda küçük bir uygulama yapalım. Önce örneği incele, sonra sen dene.','Örnek: adil oyun ile ilgili bir örneği birlikte inceleyelim.',3,1) ON DUPLICATE KEY UPDATE baslik=VALUES(baslik),alt_baslik=VALUES(alt_baslik),icerik=VALUES(icerik),ornek_metni=VALUES(ornek_metni),sira=VALUES(sira),aktif=1;
INSERT INTO ders_icerikleri (konu_kodu,kod,baslik,alt_baslik,icerik,ornek_metni,sira,aktif) VALUES ('beden_kuralli_oyun','beden_kuralli_oyun_c04','Düşün ve Söyle','Kurallı Oyunlar','kural ile ilgili kendi örneğini bul. Neden böyle düşündüğünü bir cümleyle anlat.','Örnek: kural ile ilgili bir örneği birlikte inceleyelim.',4,1) ON DUPLICATE KEY UPDATE baslik=VALUES(baslik),alt_baslik=VALUES(alt_baslik),icerik=VALUES(icerik),ornek_metni=VALUES(ornek_metni),sira=VALUES(sira),aktif=1;
INSERT INTO ders_icerikleri (konu_kodu,kod,baslik,alt_baslik,icerik,ornek_metni,sira,aktif) VALUES ('beden_kuralli_oyun','beden_kuralli_oyun_c05','Mini Tekrar','Kurallı Oyunlar','Bugün öğrendiğimiz Kurallı Oyunlar bilgisini tekrar ediyoruz. En önemli ipucu: takım.','Örnek: takım ile ilgili bir örneği birlikte inceleyelim.',5,1) ON DUPLICATE KEY UPDATE baslik=VALUES(baslik),alt_baslik=VALUES(alt_baslik),icerik=VALUES(icerik),ornek_metni=VALUES(ornek_metni),sira=VALUES(sira),aktif=1;
