INSERT INTO sorular (konu_kodu,kod,soru_turu,soru,secenekler_json,dogru_cevap,aciklama,zorluk,sira,aktif) VALUES ('serbest_dikkat','serbest_dikkat_q12','coktan_secmeli','hızlı tarama ile ilgili kendi örneğini bulmak neden yararlıdır?','["Öğrenmeyi pekiştirir","Konuyu zorlaştırır","Hiç faydası yok","Sadece zaman alır"]','Öğrenmeyi pekiştirir','Kendi örneğini üretmek öğrenmeyi pekiştirir.',3,12,1) ON DUPLICATE KEY UPDATE soru=VALUES(soru),secenekler_json=VALUES(secenekler_json),dogru_cevap=VALUES(dogru_cevap),aciklama=VALUES(aciklama),zorluk=VALUES(zorluk),sira=VALUES(sira),aktif=1;
INSERT INTO etkinlikler (konu_kodu,kod,tur,baslik,yonerge,odul_yildiz,sira,aktif) VALUES ('serbest_dikkat','serbest_dikkat_a01','mini_uygulama','Dikkat Oyunları: Hadi Deneyelim','fark bul ve aynısını bul ile ilgili iki küçük örnek bul ve yüksek sesle anlat.',1,1,1) ON DUPLICATE KEY UPDATE tur=VALUES(tur),baslik=VALUES(baslik),yonerge=VALUES(yonerge),odul_yildiz=VALUES(odul_yildiz),sira=VALUES(sira),aktif=1;
