INSERT INTO konular (ders_kodu,kod,ad,aciklama,sira,aktif) VALUES ('serbest','serbest_hafiza','Hafıza Oyunları','Hafıza Oyunları konusunda 1. sınıf seviyesinde temel kazanımlar ve uygulamalar.',2,1) ON DUPLICATE KEY UPDATE ad=VALUES(ad),aciklama=VALUES(aciklama),sira=VALUES(sira),aktif=1;
INSERT INTO ders_icerikleri (konu_kodu,kod,baslik,alt_baslik,icerik,ornek_metni,sira,aktif) VALUES ('serbest_hafiza','serbest_hafiza_c01','Keşfedelim','Hafıza Oyunları','Bugün Hafıza Oyunları konusuna giriş yapıyoruz. kart eşleştirme ile başlayalım.','Örnek: kart eşleştirme ile ilgili bir örneği birlikte inceleyelim.',1,1) ON DUPLICATE KEY UPDATE baslik=VALUES(baslik),alt_baslik=VALUES(alt_baslik),icerik=VALUES(icerik),ornek_metni=VALUES(ornek_metni),sira=VALUES(sira),aktif=1;
INSERT INTO ders_icerikleri (konu_kodu,kod,baslik,alt_baslik,icerik,ornek_metni,sira,aktif) VALUES ('serbest_hafiza','serbest_hafiza_c02','Birlikte Öğrenelim','Hafıza Oyunları','sıra hatırlama kavramını kısa bir örnekle öğrenelim ve günlük hayatta nerede kullandığımızı düşünelim.','Örnek: sıra hatırlama ile ilgili bir örneği birlikte inceleyelim.',2,1) ON DUPLICATE KEY UPDATE baslik=VALUES(baslik),alt_baslik=VALUES(alt_baslik),icerik=VALUES(icerik),ornek_metni=VALUES(ornek_metni),sira=VALUES(sira),aktif=1;
INSERT INTO ders_icerikleri (konu_kodu,kod,baslik,alt_baslik,icerik,ornek_metni,sira,aktif) VALUES ('serbest_hafiza','serbest_hafiza_c03','Hadi Deneyelim','Hafıza Oyunları','Hafıza Oyunları konusunda küçük bir uygulama yapalım. Önce örneği incele, sonra sen dene.','Örnek: görsel hafıza ile ilgili bir örneği birlikte inceleyelim.',3,1) ON DUPLICATE KEY UPDATE baslik=VALUES(baslik),alt_baslik=VALUES(alt_baslik),icerik=VALUES(icerik),ornek_metni=VALUES(ornek_metni),sira=VALUES(sira),aktif=1;
INSERT INTO ders_icerikleri (konu_kodu,kod,baslik,alt_baslik,icerik,ornek_metni,sira,aktif) VALUES ('serbest_hafiza','serbest_hafiza_c04','Düşün ve Söyle','Hafıza Oyunları','ses hafızası ile ilgili kendi örneğini bul. Neden böyle düşündüğünü bir cümleyle anlat.','Örnek: ses hafızası ile ilgili bir örneği birlikte inceleyelim.',4,1) ON DUPLICATE KEY UPDATE baslik=VALUES(baslik),alt_baslik=VALUES(alt_baslik),icerik=VALUES(icerik),ornek_metni=VALUES(ornek_metni),sira=VALUES(sira),aktif=1;
INSERT INTO ders_icerikleri (konu_kodu,kod,baslik,alt_baslik,icerik,ornek_metni,sira,aktif) VALUES ('serbest_hafiza','serbest_hafiza_c05','Mini Tekrar','Hafıza Oyunları','Bugün öğrendiğimiz Hafıza Oyunları bilgisini tekrar ediyoruz. En önemli ipucu: yer hatırlama.','Örnek: yer hatırlama ile ilgili bir örneği birlikte inceleyelim.',5,1) ON DUPLICATE KEY UPDATE baslik=VALUES(baslik),alt_baslik=VALUES(alt_baslik),icerik=VALUES(icerik),ornek_metni=VALUES(ornek_metni),sira=VALUES(sira),aktif=1;
INSERT INTO sorular (konu_kodu,kod,soru_turu,soru,secenekler_json,dogru_cevap,aciklama,zorluk,sira,aktif) VALUES ('serbest_hafiza','serbest_hafiza_q01','coktan_secmeli','Hafıza Oyunları konusunda ilk öğrendiğimiz kavram hangisidir?','["kart eşleştirme","sıra hatırlama","görsel hafıza","rastgele"]','kart eşleştirme','Bu konuda temel kavramlardan biri kart eşleştirme.',1,1,1) ON DUPLICATE KEY UPDATE soru=VALUES(soru),secenekler_json=VALUES(secenekler_json),dogru_cevap=VALUES(dogru_cevap),aciklama=VALUES(aciklama),zorluk=VALUES(zorluk),sira=VALUES(sira),aktif=1;
INSERT INTO sorular (konu_kodu,kod,soru_turu,soru,secenekler_json,dogru_cevap,aciklama,zorluk,sira,aktif) VALUES ('serbest_hafiza','serbest_hafiza_q02','coktan_secmeli','Hafıza Oyunları ile ilgili doğru seçeneği bul.','["sıra hatırlama","ilgisiz cevap","yanlış seçenek","hiçbiri"]','sıra hatırlama','sıra hatırlama bu konunun içindedir.',1,2,1) ON DUPLICATE KEY UPDATE soru=VALUES(soru),secenekler_json=VALUES(secenekler_json),dogru_cevap=VALUES(dogru_cevap),aciklama=VALUES(aciklama),zorluk=VALUES(zorluk),sira=VALUES(sira),aktif=1;
