INSERT INTO ders_icerikleri (konu_kodu,kod,baslik,alt_baslik,icerik,ornek_metni,sira,aktif) VALUES ('serbest_labirent','serbest_labirent_c01','Keşfedelim','Labirent ve Yol Bulma','Bugün Labirent ve Yol Bulma konusuna giriş yapıyoruz. başlangıç ile başlayalım.','Örnek: başlangıç ile ilgili bir örneği birlikte inceleyelim.',1,1) ON DUPLICATE KEY UPDATE baslik=VALUES(baslik),alt_baslik=VALUES(alt_baslik),icerik=VALUES(icerik),ornek_metni=VALUES(ornek_metni),sira=VALUES(sira),aktif=1;
