INSERT INTO ders_icerikleri (konu_kodu,kod,baslik,alt_baslik,icerik,ornek_metni,sira,aktif) VALUES ('serbest_gunluk_gorev','serbest_gunluk_gorev_c01','Keşfedelim','Günlük Mini Görevler','Bugün Günlük Mini Görevler konusuna giriş yapıyoruz. oda toplama ile başlayalım.','Örnek: oda toplama ile ilgili bir örneği birlikte inceleyelim.',1,1) ON DUPLICATE KEY UPDATE baslik=VALUES(baslik),alt_baslik=VALUES(alt_baslik),icerik=VALUES(icerik),ornek_metni=VALUES(ornek_metni),sira=VALUES(sira),aktif=1;
INSERT INTO ders_icerikleri (konu_kodu,kod,baslik,alt_baslik,icerik,ornek_metni,sira,aktif) VALUES ('serbest_gunluk_gorev','serbest_gunluk_gorev_c02','Birlikte Öğrenelim','Günlük Mini Görevler','kitap okuma kavramını kısa bir örnekle öğrenelim ve günlük hayatta nerede kullandığımızı düşünelim.','Örnek: kitap okuma ile ilgili bir örneği birlikte inceleyelim.',2,1) ON DUPLICATE KEY UPDATE baslik=VALUES(baslik),alt_baslik=VALUES(alt_baslik),icerik=VALUES(icerik),ornek_metni=VALUES(ornek_metni),sira=VALUES(sira),aktif=1;
